# Shared article design and four pages.
css2='''@import url('https://fonts.googleapis.com/css2?family=Kiwi+Maru:wght@300;400;500&family=Noto+Sans+JP:wght@300;400;500;600&family=Noto+Serif+JP:wght@300;400&display=swap');*{box-sizing:border-box}body{margin:0;min-height:100vh;color:#625d70;font-family:"Noto Sans JP","Yu Gothic",sans-serif;background:radial-gradient(circle at 12% 8%,rgba(255,211,232,.55),transparent 22%),radial-gradient(circle at 87% 12%,rgba(207,237,255,.5),transparent 24%),linear-gradient(180deg,#fffafd,#faf8ff);transition:.8s;overflow-x:hidden}body.night,body.deep{color:#eceaff;background:linear-gradient(180deg,#31396c,#1d2147 55%,#101126)}a{color:inherit}.topbar{height:72px;display:flex;align-items:center;border-bottom:1px solid rgba(100,86,120,.12);background:rgba(255,255,255,.78);backdrop-filter:blur(12px)}body.night .topbar,body.deep .topbar{background:rgba(26,29,63,.8);border-color:rgba(255,255,255,.06)}.wrap{width:min(900px,calc(100% - 36px));margin:auto}.brand{font-family:"Kiwi Maru";text-decoration:none;font-size:17px}.brand small{display:block;font-family:"Noto Sans JP";font-size:7px;letter-spacing:.18em;color:#9c94a6}.article{padding:82px 0 110px}.meta{display:flex;gap:14px;align-items:center;font-size:9px;color:#9b93a5}.tag{padding:6px 10px;border-radius:999px;background:#ffe0ed;color:#9b607e}.title{font-family:"Kiwi Maru";font-weight:400;font-size:clamp(31px,6vw,58px);line-height:1.45;margin:24px 0 36px}.content{font-size:14px;line-height:2.2}.content p{margin:0 0 24px}.box{margin:34px 0;padding:24px 26px;border-radius:22px;background:rgba(255,255,255,.78);border:1px solid rgba(105,92,126,.12)}body.night .box,body.deep .box{background:rgba(255,255,255,.04);border-color:rgba(255,255,255,.07)}.back{display:inline-flex;margin-top:42px;padding:12px 20px;border-radius:999px;text-decoration:none;background:linear-gradient(135deg,#ffd7e8,#d7edff);color:#625e74;font-size:12px;font-weight:600}.night-only{display:none}body.night .night-only,body.deep .night-only{display:block}.day-only{display:block}body.night .day-only,body.deep .day-only{display:none}@keyframes shake{0%,100%{transform:translate(0)}25%{transform:translate(.8px,-.4px)}50%{transform:translate(-.8px,.6px)}75%{transform:translate(.5px,.5px)}}@keyframes flicker{0%,7%,10%,62%,66%,100%{opacity:1}8%,64%{opacity:.18}9%,65%{opacity:.7}}body:before{content:"";position:fixed;inset:-8%;pointer-events:none;z-index:10;opacity:0;background:repeating-linear-gradient(0deg,rgba(255,255,255,.2) 0,rgba(255,255,255,.2) 1px,transparent 1px,transparent 4px);mix-blend-mode:screen}body.night:before{opacity:.07}body.deep:before{opacity:.13}.glitch{display:inline-block}body.night .glitch,body.deep .glitch{animation:shake .13s infinite}.red{color:#c85d6c}body.night .red,body.deep .red{color:#ff6a72;text-shadow:0 0 12px rgba(255,80,90,.25)}.flicker{animation:flicker 2.4s infinite}.huge{font-family:"Noto Serif JP","Yu Mincho",serif;font-size:clamp(62px,14vw,150px);line-height:1.06;margin:30px 0}body.night .huge,body.deep .huge{color:#ff626b;animation:shake .13s infinite,flicker 2.2s infinite}@media(max-width:600px){.article{padding-top:58px}.content{font-size:13px}.title{font-size:36px}}'''
common='''const KEY="mokomoko_summerland_horror_v1";let S=JSON.parse(localStorage.getItem(KEY)||'{"phase":0,"autoApplied":false}');if(S.phase>=3)document.body.classList.add("deep");else if(S.phase>=2)document.body.classList.add("night");'''
def page(fn,date,tag,title,body,extra=''):
    html=f'''<!doctype html><html lang="ja"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="icon" href="assets/favicon.svg" type="image/svg+xml"><title>{title}｜もこもこランド</title><style>{css2}</style></head><body><header class="topbar"><div class="wrap"><a class="brand" href="index.html#top">もこもこランド<small>MOKOMOKO LAND OFFICIAL</small></a></div></header><main class="article"><article class="wrap"><div class="meta"><time>{date}</time><span class="tag">{tag}</span></div><h1 class="title">{title}</h1><div class="content">{body}</div><a class="back" href="index.html#news">← インフォメーションへ戻る</a></article></main><script>{common}{extra}</script></body></html>'''
    Path(fn).write_text(html,encoding='utf-8')
page('news-illumination.html','2026.09.10','お知らせ','ナイトイルミネーション開催のお知らせ','''<p>本日より、期間限定イベント「ナイトイルミネーション」を開催いたします。</p><p>夕暮れから閉園まで、園内のアトラクションや並木道をやさしい光で彩ります。昼間とは少し違う、もこもこランドの景色をお楽しみください。</p><div class="box"><strong>開催時間</strong><br>17:00〜21:00<br><strong>開催場所</strong><br>園内各所</div><p class="day-only">皆さまのご来園を、キャスト一同心よりお待ちしております。</p><p class="night-only red glitch">消灯後も点いている照明には、近づかないでください。</p>''')
